  static final _bounds = _paths
      .map((path) => path.getBounds())
      .reduce((a, b) => a.expandToInclude(b));

  @override
  void paint(Canvas canvas, Size size) {
    final scale = (size.width / _bounds.width).clamp(
      0.0,
      size.height / _bounds.height,
    );
    canvas.save();
    canvas.translate(
      (size.width - _bounds.width * scale) / 2,
      (size.height - _bounds.height * scale) / 2,
    );
    canvas.scale(scale);
    canvas.translate(-_bounds.left, -_bounds.top);
    final paint = Paint()..color = color;
    for (final path in _paths) {
      canvas.drawPath(path, paint);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_BrandPainter oldDelegate) => color != oldDelegate.color;
